<script>
function dealerQuickOrderForm() {
    return {
        optionsUrl: @js(route('dealer.web.quick.options')),
        wardsUrl: @js(url('/api/administrative/wards')),
        items: @js($initialItems), skuSearch: '', results: [], submitting: false,
        previewFresh: @js($review !== null),
        savedId: @js((string) old('shipping_address_id', $addresses->first()?->id ?? '')),
        provinceCode: @js((string) old('shipping_province_code', '')),
        wardCode: @js((string) old('shipping_ward_code', '')),
        wards: [],
        init() { if (this.provinceCode) this.loadWards(); },
        async loadSkus() {
            if (this.skuSearch.trim().length < 2) { this.results = []; return; }
            try { const response = await fetch(this.optionsUrl + '?' + new URLSearchParams({search: this.skuSearch.trim()}), {headers: {'Accept': 'application/json'}}); this.results = response.ok ? (await response.json()).data : []; } catch { this.results = []; }
        },
        addSku(option) {
            if (!this.items.some(item => Number(item.product_variant_id) === option.id) && this.items.length < 50) this.items.push({product_variant_id: option.id, quantity: String(Math.ceil(Number(option.minimum_quantity))), label: option.label, unit_price: option.unit_price, minimum_quantity: option.minimum_quantity});
            this.skuSearch = ''; this.results = []; this.previewFresh = false;
        },
        async loadWards() {
            if (!this.provinceCode) { this.wards = []; return; }
            try { const response = await fetch(this.wardsUrl + '?' + new URLSearchParams({province_code: this.provinceCode}), {headers: {'Accept': 'application/json'}}); this.wards = response.ok ? (await response.json()).data : []; } catch { this.wards = []; }
        },
    };
}
</script>
